package com.mantou.salesdialer.contacts;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.security.MessageDigest;
public final class PhoneParserParityCheck {public static void main(String[] args)throws Exception{BufferedReader in=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8));int count=0;for(String line;(line=in.readLine())!=null;){String[] fields=line.split("\\t",-1);if(fields.length!=3)throw new IllegalStateException("INVALID_PARITY_VECTOR");String raw=new String(Base64.getDecoder().decode(fields[0]),StandardCharsets.UTF_8);var p=PhoneIntakeModel.parse(raw);String hash=p.canonical==null?"":HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(p.canonical.getBytes(StandardCharsets.UTF_8)));if(!fields[1].equals(p.status)||!fields[2].equals(hash))throw new IllegalStateException("HOST_PARSER_MISMATCH_AT_"+count);count++;}if(count<500||count>1000)throw new IllegalStateException("BOUNDED_PARITY_REQUIRED");System.out.println("T660 host/native parser parity passed: "+count+" generated vectors; no customer data");}}
